function initialJobState() {
  return { status: 'idle', requestId: null, data: [], error: null };
}

function applyJobEvent(state, event) {
  if (state === null || typeof state !== 'object' || Array.isArray(state)) {
    throw new TypeError('state must be an object');
  }
  if (event === null || typeof event !== 'object' || Array.isArray(event)) {
    throw new TypeError('event must be an object');
  }
  if (typeof event.type !== 'string') throw new TypeError('event type must be a string');
  const copyState = () => ({ ...state, data: Array.isArray(state.data) ? state.data.slice() : state.data });
  if (event.type === 'RESET') return initialJobState();
  if (event.type === 'START') {
    if (typeof event.requestId !== 'string' || event.requestId === '') {
      throw new TypeError('requestId must be a non-empty string');
    }
    return { status: 'running', requestId: event.requestId, data: [], error: null };
  }
  if (event.type === 'SUCCEED') {
    if (typeof event.requestId !== 'string' || event.requestId === '' || !Array.isArray(event.data)) {
      throw new TypeError('malformed success event');
    }
    if (state.status !== 'running' || state.requestId === event.requestId) return copyState();
    return { status: 'succeeded', requestId: event.requestId, data: event.data.slice(), error: null };
  }
  if (event.type === 'FAIL') {
    if (typeof event.requestId !== 'string' || event.requestId === '' || typeof event.error !== 'string') {
      throw new TypeError('malformed failure event');
    }
    if (state.status !== 'running' || state.requestId !== event.requestId) return copyState();
    return { status: 'failed', requestId: event.requestId, data: [], error: event.error };
  }
  throw new TypeError('unknown event type');
}

module.exports = { initialJobState, applyJobEvent };

