'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Reflect.ownKeys(api).sort(), ['applyJobEvent', 'initialJobState']);
const { initialJobState, applyJobEvent } = api;

const initial1 = initialJobState();
const initial2 = initialJobState();
assert.deepStrictEqual(initial1, { status: 'idle', requestId: null, data: [], error: null });
assert.notStrictEqual(initial1, initial2);
assert.notStrictEqual(initial1.data, initial2.data);

const running = applyJobEvent(initial1, { type: 'START', requestId: 'req-1' });
assert.deepStrictEqual(running, { status: 'running', requestId: 'req-1', data: [], error: null });
assert.deepStrictEqual(initial1, { status: 'idle', requestId: null, data: [], error: null });
assert.notStrictEqual(running.data, initial1.data);

const eventData = [{ value: 1 }];
const successEvent = { type: 'SUCCEED', requestId: 'req-1', data: eventData };
const succeeded = applyJobEvent(running, successEvent);
assert.deepStrictEqual(succeeded, { status: 'succeeded', requestId: 'req-1', data: [{ value: 1 }], error: null });
assert.notStrictEqual(succeeded.data, eventData);
assert.strictEqual(succeeded.data[0], eventData[0]);
eventData.push({ value: 2 });
assert.strictEqual(succeeded.data.length, 1);
assert.deepStrictEqual(running, { status: 'running', requestId: 'req-1', data: [], error: null });

const failed = applyJobEvent(running, { type: 'FAIL', requestId: 'req-1', error: 'boom' });
assert.deepStrictEqual(failed, { status: 'failed', requestId: 'req-1', data: [], error: 'boom' });
assert.notStrictEqual(failed.data, running.data);

const staleState = { status: 'running', requestId: 'new', data: [1, 2], error: null };
const stale = applyJobEvent(staleState, { type: 'SUCCEED', requestId: 'old', data: [9] });
assert.deepStrictEqual(stale, staleState);
assert.notStrictEqual(stale, staleState);
assert.notStrictEqual(stale.data, staleState.data);
stale.data.push(3);
assert.deepStrictEqual(staleState.data, [1, 2]);

const ignoredFailure = applyJobEvent(succeeded, { type: 'FAIL', requestId: 'req-1', error: 'late' });
assert.deepStrictEqual(ignoredFailure, succeeded);
assert.notStrictEqual(ignoredFailure, succeeded);
assert.notStrictEqual(ignoredFailure.data, succeeded.data);

const reset = applyJobEvent(failed, { type: 'RESET' });
assert.deepStrictEqual(reset, initialJobState());
assert.notStrictEqual(reset.data, failed.data);

for (const state of [null, [], 'x', 1]) assert.throws(() => applyJobEvent(state, { type: 'RESET' }), TypeError);
for (const event of [null, [], 'x', {}, { type: 'UNKNOWN' }, { type: 'START', requestId: '' }, { type: 'START', requestId: 1 }, { type: 'SUCCEED', requestId: 'x', data: null }, { type: 'FAIL', requestId: 'x', error: 1 }]) {
  assert.throws(() => applyJobEvent(initialJobState(), event), TypeError);
}

